INSERT INTO courses (id, slug, title, summary, description, status, created_at, updated_at, published_at) VALUES
('10000000-0000-4000-8000-000000000001', 'go-backend-foundations', 'Go: фундамент надійного бекенду', 'Побудуйте HTTP API з чіткими межами домену, PostgreSQL і перевірками.', 'Практичний курс зі створення Go API. Розглянемо модульну архітектуру, контракти, транзакції PostgreSQL, обробку помилок і тести. Каталог демонструє структуру платформи; відеоуроки й оплата поки недоступні.', 'published', '2026-08-01T10:00:00Z', '2026-09-03T10:00:00Z', '2026-09-03T10:00:00Z'),
('10000000-0000-4000-8000-000000000002', 'react-accessible-interfaces', 'React: доступні інтерфейси', 'Створюйте зрозумілі інтерфейси з React, TypeScript і клавіатурною навігацією.', 'Від семантичного HTML до стану застосунку: компоненти, форми, навігація та доступність. Працюємо з явними контрактами й перевіряємо поведінку користувача. Це демонстраційна сторінка курсу foundation-версії.', 'published', '2026-08-01T10:00:00Z', '2026-09-02T10:00:00Z', '2026-09-02T10:00:00Z'),
('10000000-0000-4000-8000-000000000003', 'system-design-practice', 'Системний дизайн на практиці', 'Навчіться обирати прості архітектурні рішення й перевіряти їхні обмеження.', 'Проєктування починається з потреб користувача. У курсі розбираємо межі модулів, узгодженість даних, черги, спостережуваність і розвиток системи. Навчальні матеріали будуть доступні в наступних етапах платформи.', 'published', '2026-08-01T10:00:00Z', '2026-09-01T10:00:00Z', '2026-09-01T10:00:00Z'),
('10000000-0000-4000-8000-000000000004', 'draft-course', 'Чернетка курсу', 'Приклад неопублікованого курсу.', 'Цей запис перевіряє приховування чернеток у публічному каталозі.', 'draft', '2026-08-01T10:00:00Z', '2026-08-01T10:00:00Z', NULL),
('10000000-0000-4000-8000-000000000005', 'archived-course', 'Архівний курс', 'Приклад архівного курсу.', 'Цей запис перевіряє приховування архівних курсів у публічному каталозі.', 'archived', '2026-08-01T10:00:00Z', '2026-09-01T10:00:00Z', '2026-08-02T10:00:00Z')
